SELECT d.name AS department_name, e.name AS manager_name
FROM hr.departments d
LEFT JOIN hr.employees e ON d.manager_id = e.id;

SELECT d.name, d.budget
FROM hr.departments d
JOIN hr.employees e ON d.manager_id = e.id;

SELECT id, user_id, account_type, balance, currency, opened_at, closed_at
FROM fintech.accounts
WHERE balance > 2000 AND account_type IN ('savings', 'checking');

SELECT id, employee_id, request_type, start_date, end_date, status
FROM hr.time_off_requests
WHERE status = 'pending' AND julianday('now') - julianday(start_date) > 30;

SELECT COUNT(*) AS num_employees
FROM hr.performance_reviews
WHERE rating >= 4.5 AND review_period = 'Q1 2024';

SELECT id, user_id, account_type, balance, currency, opened_at, closed_at
FROM fintech.accounts
WHERE balance > 1000 AND account_type IN ('checking', 'savings');

SELECT e.name
FROM hr.employees e
WHERE strftime('%Y', e.hire_date) = '2024';

SELECT AVG(balance) AS average_balance
FROM accounts
WHERE closed_at IS NULL;

SELECT *
FROM hr.employees
WHERE email LIKE '%example%';

SELECT name, category, price
FROM products
WHERE stock < 5;

SELECT o.name
FROM saas.organizations o
WHERE o.churned_at IS NULL AND o.plan LIKE '%pro%';

SELECT plan, mrr
FROM subscriptions
WHERE strftime('%Y', started_at) = strftime('%Y', 'now');

SELECT name, price, stock
FROM products
WHERE price > 50 AND stock <= 5;

SELECT id, user_id, account_type
FROM fintech.accounts
WHERE balance > (SELECT AVG(balance) FROM fintech.accounts);

SELECT SUM(p.price * p.stock) AS total_stock_value
FROM products p
WHERE p.category = 'clothing';

SELECT *
FROM saas.users
WHERE role = 'owner' AND LOWER(email) LIKE '%example%';

SELECT e.title
FROM hr.employees e
WHERE strftime('%Y', e.hire_date) = '2022';

SELECT status, COUNT(*) AS request_count
FROM hr.time_off_requests
GROUP BY status;
